# Make prose readable without mutating identifiers or links.
import re
prosekeys={'trial_acronym','publication_title','evidence_context','study_design','trial_population','intervention','comparator','primary_endpoint','limitations','relevance_summary','trial','population','comparison','applicability','outcome','result','label'}
def tidy(v):return re.sub(r'(?<=\d)(?=[A-Za-z])',' ',re.sub(r'(?<=[A-Za-z])(?=\d)',' ',v)).replace('95%CI','95% CI').replace('HR0.','HR 0.')
def walk(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if isinstance(v,str) and k in prosekeys:x[k]=tidy(v)
   elif isinstance(v,list) and k in ['key_findings','limitations','integration_notes']:x[k]=[tidy(t) if isinstance(t,str) else t for t in v]
   else:walk(v)
 elif isinstance(x,list):
  for v in x:walk(v)
walk(out)
